import contextlib
import io
import unittest

from textkit.cli import main
from textkit.rot import rot


def run(*argv):
    out, err = io.StringIO(), io.StringIO()
    with contextlib.redirect_stdout(out), contextlib.redirect_stderr(err):
        code = main(list(argv))
    return code, out.getvalue(), err.getvalue()


class RotTest(unittest.TestCase):
    def test_rot13_default_example(self):
        self.assertEqual(rot("Hello, World!", 13), "Uryyb, Jbeyq!")

    def test_wraps_around_end_of_alphabet(self):
        self.assertEqual(rot("xyz", 3), "abc")
        self.assertEqual(rot("XYZ", 1), "YZA")

    def test_keeps_case(self):
        self.assertEqual(rot("AbC", 1), "BcD")

    def test_other_characters_unchanged(self):
        self.assertEqual(rot("a1 b-2 é ñ!\n", 1), "b1 c-2 é ñ!\n")

    def test_negative_shift(self):
        self.assertEqual(rot("abc", -1), "zab")

    def test_large_and_negative_large_shifts(self):
        self.assertEqual(rot("abc", 27), "bcd")
        self.assertEqual(rot("abc", -53), "zab")
        self.assertEqual(rot("abc", 26), "abc")
        self.assertEqual(rot("abc", 0), "abc")

    def test_rot_twice_with_13_restores_text(self):
        self.assertEqual(rot(rot("Round Trip", 13), 13), "Round Trip")

    def test_non_int_raises_value_error(self):
        for n in (1.5, "1", None, [1]):
            with self.subTest(n=n), self.assertRaises(ValueError):
                rot("abc", n)

    def test_bool_raises_value_error(self):
        for n in (True, False):
            with self.subTest(n=n), self.assertRaises(ValueError):
                rot("abc", n)


class RotCommandTest(unittest.TestCase):
    def test_default_is_rot13(self):
        self.assertEqual(run("rot", "Hello, World!"), (0, "Uryyb, Jbeyq!\n", ""))

    def test_n_option(self):
        self.assertEqual(run("rot", "abc", "--n", "-1"), (0, "zab\n", ""))
        self.assertEqual(run("rot", "abc", "--n", "27"), (0, "bcd\n", ""))

    def test_non_int_n_exits_2_with_error(self):
        code, out, err = run("rot", "abc", "--n", "1.5")
        self.assertEqual(code, 2)
        self.assertEqual(out, "")
        self.assertTrue(err.startswith("error: "))

    def test_string_n_exits_2_with_error(self):
        code, out, err = run("rot", "abc", "--n", "x")
        self.assertEqual(code, 2)
        self.assertEqual(out, "")
        self.assertTrue(err.startswith("error: "))

    def test_listed_in_commands(self):
        _, out, _ = run("commands")
        self.assertIn("rot", out.split())


if __name__ == "__main__":
    unittest.main()

